 [['tailor shop','jackets',[9,11,10,7,4,1],6],['jam kitchen','jars',[7,9,8,6,3,1],4],['tile workshop','tiles',[12,14,13,9,5,2],5]].forEach(([s,u,m,n])=>put('prodfn',`A fictional ${s} adds workers one at a time to fixed equipment. The marginal products of workers 1 to 6 are ${m.join(', ')} ${u} a day. What is total product with ${n} workers, in ${u} a day?`,m.slice(0,n).reduce((a,b)=>a+b,0),tab(`The ${s}`,[['marginal products',m.join(', ')],['workers',String(n)]]),`Total product is the sum of the first ${n} marginal products: ${m.slice(0,n).join(' + ')} = ${m.slice(0,n).reduce((a,b)=>a+b,0)}.`));
